For the time being, I've come out a workaround, assigning the instantiated XAuthMiddleware instance in the **_parseCaddyfile_** to a global variable __XAuthMiddleware_, and then checking in the New() func for the ModuleInfo if __XAuthMiddleware_ is not nil, if so, just reusing it instead of creating a new instancing by calling _NewXAuth()_ defined as below:

```

func NewXAuth() *XAuthMiddleware {
	fmt.Println("XAuthMiddleware NewXAuth")
	xauth := new(XAuthMiddleware)
	sessionManager := scs.New()
	sessionManager.Lifetime = 2 * time.Hour
	sessionManager.IdleTimeout = 30 * time.Minute
	sessionManager.Cookie.Persist = false
	xauth.SessionManager = &MySessionManager{
		SessionManager: sessionManager,
		IPCheck:        false,
	}
	xauth.OidcConfig = &oidc.OIDCConfig{}
	xauth.TokenConfig = &TokenConfig{
		JWTHeader: "X-JWT-Token",
	}
	return xauth
}
```

